FROM   sales.daily_sales
ORDER BY y, m, d, product_name;

CREATE PROCEDURE Sales.GetTopProducts
    @CategoryID INT,
    @TopN INT = 5
AS
BEGIN
    SELECT TOP (@TopN)
        p.product_name,
        p.list_price
    FROM   production.products p
    WHERE  p.category_id = @CategoryID
    ORDER BY p.list_price DESC;
END;

-- Use default @TopN (5)
EXEC Sales.GetTopProducts @CategoryID = 1;

-- Override @TopN
EXEC Sales.GetTopProducts @CategoryID = 1, @TopN = 10;
